<template>
  <Alert>
    <Info class="mt-2.5" />
    <AlertTitle class="flex flex-wrap items-center justify-between min-h-9 gap-2">
      Note
      <div v-if="!(isEditing || isNoteDraft)" class="float-right flex flex-row gap-2">
        <template v-if="note">
          <Button variant="outline" :prepend-icon="Pencil" @click="isEditing = true">Edit</Button>
          <ConfirmationDialog
            title="Remove note?"
            description="Are you sure you want to remove note content?"
            confirm-btn-variant="destructive"
            confirm-btn-text="Remove"
            @confirm="onRemove"
          >
            <Button variant="outline" :prepend-icon="Trash" :loading="isRemoveLoading">Remove</Button>
          </ConfirmationDialog>
        </template>
        <template v-else>
          <Button variant="outline" :prepend-icon="NotebookPenIcon" @click="isEditing = true">Create a Note</Button>
        </template>
      </div>
    </AlertTitle>
    <AlertDescription>
      <form v-if="isEditing || isNoteDraft" class="w-full mt-2" @submit="onSubmit">
        <FormField v-slot="{ componentField }" name="note">
          <FormItem>
            <FormControl>
              <Textarea placeholder="Enter your note here" class="resize-none" v-bind="componentField" />
            </FormControl>
            <FormDescription class="text-wrap">{{ resolvedFormDescription }}</FormDescription>
            <FormMessage />
          </FormItem>
        </FormField>
        <div class="flex flex-row gap-2 justify-end mt-2">
          <Button variant="outline" type="button" @click="cancelEditing">Cancel</Button>
          <Button type="submit" :loading="isUpdateLoading">Save</Button>
        </div>
      </form>
      <template v-else-if="note">
        <AppMarkdown :markdown="note.content" />
        <p v-if="note.updated_at" class="text-xs text-muted-foreground mt-2">
          Last updated {{ formatDateToFormat(note.updated_at, 'MM/dd/yyyy, hh:mm aaa') }}
          <span v-if="note.updated_by"> by <InlineEntityUser :user-id="note.updated_by" /> </span>
        </p>
      </template>
      <p v-else class="text-sm text-muted-foreground">
        No note has been created yet. You can add a note to keep track of important information.
      </p>
    </AlertDescription>
  </Alert>
</template>

<script setup lang="ts">
import { Alert, AlertDescription, AlertTitle } from '~/components/ui/alert';
import { Info, Pencil, Trash, NotebookPenIcon } from 'lucide-vue-next';

import { Button } from '@/components/ui/button';
import { FormControl, FormDescription, FormField, FormItem, FormMessage } from '@/components/ui/form';
import { Textarea } from '@/components/ui/textarea';

import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import * as z from 'zod';
import type { Note } from '~/client';

const props = defineProps<{
  note: Note | null;
  isNoteDraft: boolean;
  changeNoteDraft: () => void;
  createNote?: (content: string) => Promise<void>;
  updateNote: (content: string) => Promise<void>;
  removeNote: () => Promise<void>;
  isUpdateLoading: boolean;
  isRemoveLoading: boolean;
  formDescription?: string;
}>();

const resolvedFormDescription = computed(
  () => props.formDescription ?? 'This note is visible to other managers and administrators'
);

const isEditing = ref<boolean>(false);

const formSchema = toTypedSchema(
  z.object({
    note: z.string().nonempty('Text is required'),
  })
);

const { handleSubmit, setFieldValue } = useForm({
  validationSchema: formSchema,
});

watch([isEditing, () => props.isNoteDraft], () => {
  setFieldValue('note', props.note?.content ?? '');
});

function cancelEditing() {
  isEditing.value = false;
  if (props.isNoteDraft) props.changeNoteDraft();
}

const onSubmit = handleSubmit(async ({ note }) => {
  if (props.note === null && props.createNote) {
    await props.createNote(note);
  } else {
    await props.updateNote(note);
  }
  isEditing.value = false;
  if (props.isNoteDraft) props.changeNoteDraft();
});

async function onRemove() {
  await props.removeNote();
}
</script>
